<template>
  <section :aria-label="`${label}全院冻结审计`">
    <p>超级管理员核对全院原版本、当前治理和失效原因。失效原件只保留冻结审计；管理权不能代替实际医生签署或继续执行旧任务。</p>
    <el-form v-if="allowed" inline @submit.prevent="query"><el-form-item label="患者ID"><el-input v-model="filters.patient_id" :aria-label="`${label}审计患者ID`" inputmode="numeric" /></el-form-item><el-form-item label="原住院ID"><el-input v-model="filters.admission_id" :aria-label="`${label}审计原住院ID`" /></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" :aria-label="`${label}审计状态`" clearable><el-option label="活动" value="active" /><el-option label="已撤销" value="revoked" /></el-select></el-form-item><el-button native-type="submit" :loading="loading">查询{{ label }}全院评估</el-button></el-form>
    <p v-if="error" role="alert">{{ error }}</p><el-table :data="items" v-loading="loading" :aria-label="`${label}全院评估目录`"><el-table-column label="原评估ID" min-width="250"><template #default="{row}">{{ row[idKey] }}</template></el-table-column><el-table-column label="原患者与住院" min-width="260"><template #default="{row}">#{{ row.patient_id }} · {{ row.admission_id }}</template></el-table-column><el-table-column prop="evaluation_at" label="当前回顾登记UTC" min-width="230" /><el-table-column label="治理"><template #default="{row}">{{ row.status==='revoked'?'已撤销':'活动' }} · v{{ row.revision }}<el-button @click="inspect(row)">核对冻结{{ label }}</el-button></template></el-table-column></el-table><el-pagination v-if="total>50" v-model:current-page="page" :total="total" :page-size="50" layout="prev,pager,next" @current-change="load" />
    <el-dialog v-model="detailOpen" :title="`${label}完整冻结评估审计`" width="min(1150px,96vw)" @closed="!detailOpen&&clearDetail()"><div v-if="allowed" v-loading="inspecting"><p v-if="detailError" role="alert">{{ detailError }}</p><template v-if="detail"><p class="hash">原评估 {{ detail[idKey] }}；患者 #{{ detail.patient_id }}；原住院 {{ detail.admission_id }}<br />完整原文 {{ detail.content_hash }}<br />完整公开投影 {{ detail.projection_hash }}<br />当前治理 {{ detail.governance_hash }} · {{ detail.status }} · v{{ detail.revision }}</p><p>当前原来源资格：{{ detail.eligible?'仍可纳入当前重新核对':'失效，仅保留冻结审计' }}；原因 {{ detail.exclusion_reasons.join('、')||'无' }}。</p>
      <p>原签署医生记录 {{ detail.snapshot.author_qualification.doctor_id }}；签署时身份 {{ detail.snapshot.author_qualification.role_at_creation }}；原当前回顾 {{ detail.evaluation_at }}，不冒称旧截止时已知。</p>
      <template v-if="!changeMode"><p>固定24小时 {{ detail.period_start }} 至 {{ detail.period_end }}；原资料可用截止 {{ detail.as_of }}。完整原成员 {{ detail.snapshot.manifest.members.length }} 项，未只保留最高值或当前显示页。</p><el-table :data="members" aria-label="SOFA审计全部原成员分页"><el-table-column prop="kind" label="原来源类型" /><el-table-column prop="identifier" label="原标识" min-width="250" /><el-table-column prop="temporal_role" label="日内或日前前缀" /><el-table-column prop="content_hash" label="原完整摘要" min-width="250" /></el-table><el-pagination v-if="detail.snapshot.manifest.members.length>20" v-model:current-page="memberPage" :total="detail.snapshot.manifest.members.length" :page-size="20" layout="prev,pager,next" /></template>
      <template v-else><p>当前日原评估 {{ detail.current_assessment_id }}；原住院 {{ detail.snapshot.current_assessment.admission_id }}。</p><p v-if="detail.snapshot.baseline_assessment">真实基线原评估 {{ detail.baseline_assessment_id }}；其独立原住院 {{ detail.snapshot.baseline_assessment.admission_id }}，没有改绑为当前住院。</p><p v-else>原基线策略 {{ detail.snapshot.attestation.baseline.mode }}；条件性假设与未知分别保留，不从缺少资料补零。</p><p>原感染 {{ detail.infection_source_id }}；原发作 {{ detail.snapshot.infection_source.payload.onset_at??'未知' }}；原系统登记 {{ detail.snapshot.infection_source.recorded_at }}。</p></template>
      <details><summary>核对完整原临床判读、覆盖与依据</summary><pre>{{ JSON.stringify(detail.snapshot.attestation,null,2) }}</pre></details><details><summary>院内核对全部冻结原件和完整关联链</summary><p>以下为院内审计原文。</p><pre>{{ JSON.stringify(detail.snapshot,null,2) }}</pre></details><details><summary>核对固定公开原量投影</summary><pre>{{ JSON.stringify(detail.specialist_source,null,2) }}</pre></details>
      <template v-if="detail.can_revoke===true&&detail.status==='active'"><el-input v-model="reason" :aria-label="`${label}审计撤销依据`" type="textarea" maxlength="1000" placeholder="明确记录原版本撤销依据" /><el-button type="danger" :loading="acting" :disabled="acting||!reason.trim()" @click="revoke">撤销冻结{{ label }}</el-button></template><p v-if="detail.status==='revoked'">原撤销 {{ detail.revoked_at }}：{{ detail.revoke_reason }}；原内容和公开投影不改写，不能恢复旧版本。</p>
    </template></div></el-dialog>
  </section>
</template>
<script setup>
import {computed,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from "vue";
import {useStore} from "vuex";
import {getAdminSofaAssessment,getAdminSofaAssessments,getAdminSofaChangeAssessment,getAdminSofaChangeAssessments,revokeSofaAssessment,revokeSofaChangeAssessment,sofaRevocationMatches,verifySofaAssessment,verifySofaChangeAssessment} from "@/api/aiSofa";
import {supportCanonical,supportHash,supportId} from "@/api/inpatientSupport";
const props=defineProps({changeMode:{type:Boolean,default:false}}),store=useStore(),allowed=computed(()=>!!store.state.user.accessToken&&(store.getters["user/permissions"]||[]).includes("super_admin")),label=computed(()=>props.changeMode?"SOFA变化":"SOFA日评估"),idKey=computed(()=>props.changeMode?"change_assessment_id":"assessment_id");
const filters=ref({patient_id:"",admission_id:"",status:""}),items=ref([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(""),detailOpen=ref(false),detail=ref(null),inspecting=ref(false),detailError=ref(""),reason=ref(""),acting=ref(false),memberPage=ref(1);
let epoch=0,listSeq=0,detailSeq=0,paused=false,alive=true;const session=()=>supportCanonical([store.state.user.accessToken,store.getters["user/permissions"]||[],props.changeMode]),capture=()=>({epoch,session:session()}),current=ticket=>alive&&!paused&&allowed.value&&ticket.epoch===epoch&&ticket.session===session(),queryKey=()=>supportCanonical([filters.value,page.value]);
const api=computed(()=>props.changeMode?{list:getAdminSofaChangeAssessments,detail:getAdminSofaChangeAssessment,revoke:revokeSofaChangeAssessment,verify:verifySofaChangeAssessment}:{list:getAdminSofaAssessments,detail:getAdminSofaAssessment,revoke:revokeSofaAssessment,verify:verifySofaAssessment}),members=computed(()=>detail.value?.snapshot.manifest?.members.slice((memberPage.value-1)*20,memberPage.value*20)||[]);
function clearDetail(){detailSeq++;detail.value=null;detailError.value=reason.value="";inspecting.value=acting.value=false;memberPage.value=1;}
function reset(){epoch++;listSeq++;detailOpen.value=false;clearDetail();items.value=[];total.value=0;page.value=1;loading.value=false;error.value="";}
function query(){page.value=1;detailOpen.value=false;clearDetail();load();}
async function load(){const ticket=capture(),seq=++listSeq,key=queryKey();items.value=[];error.value="";if(!current(ticket))return;loading.value=true;try{const patient=filters.value.patient_id.trim(),admission=filters.value.admission_id.trim();if(patient&&(!/^[1-9]\d*$/.test(patient)||!Number.isSafeInteger(Number(patient))||Number(patient)>2147483647)||admission&&!supportId(admission))throw new Error("请填写规范患者ID及原住院UUID");const params={page:page.value,page_size:50,...(patient?{patient_id:Number(patient)}:{}),...(admission?{admission_id:admission}:{}),...(filters.value.status?{status:filters.value.status}:{})},response=await api.value.list(params),data=response.data;if(!current(ticket)||seq!==listSeq||key!==queryKey())return;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.items.some(row=>!supportId(row[idKey.value])||!Number.isSafeInteger(row.patient_id)||row.patient_id<1||!supportId(row.admission_id)||!supportHash(row.content_hash)||!supportHash(row.projection_hash)||patient&&row.patient_id!==Number(patient)||admission&&row.admission_id!==admission))throw new Error("SOFA全院目录与指定范围不一致");items.value=data.items;total.value=data.total;}catch(failure){if(current(ticket)&&seq===listSeq)error.value=failure?.message||"SOFA全院审计目录读取失败";}finally{if(current(ticket)&&seq===listSeq)loading.value=false;}}
async function inspect(original){if(!allowed.value||paused)return;clearDetail();detailOpen.value=true;inspecting.value=true;const ticket=capture(),seq=detailSeq;try{const response=await api.value.detail(original[idKey.value]),row=response.data;if(!current(ticket)||seq!==detailSeq||!detailOpen.value)return;if(row[idKey.value]!==original[idKey.value]||row.content_hash!==original.content_hash||row.projection_hash!==original.projection_hash||!await api.value.verify(row,original.patient_id,original.admission_id,true))throw new Error("SOFA冻结原件、完整投影或指定范围未能核对");if(current(ticket)&&seq===detailSeq&&detailOpen.value)detail.value=row;}catch(failure){if(current(ticket)&&seq===detailSeq)detailError.value=failure?.message||"SOFA冻结审计原件读取失败";}finally{if(current(ticket)&&seq===detailSeq)inspecting.value=false;}}
async function revoke(){const original=detail.value;if(!original||original.can_revoke!==true||original.status!=="active"||!reason.value.trim()||acting.value)return;const ticket=capture(),seq=detailSeq,body={patient_id:original.patient_id,admission_id:original.admission_id,expected_revision:original.revision,reason:reason.value.trim()};acting.value=true;try{const response=await api.value.revoke(original[idKey.value],body);if(!current(ticket)||seq!==detailSeq||!detailOpen.value)return;if(!await sofaRevocationMatches(response.data,original,original.patient_id,original.admission_id,props.changeMode))throw new Error("SOFA撤销回执与原版本、范围或治理摘要不一致");let row=response.data;if(!row.snapshot){const fresh=await api.value.detail(original[idKey.value]);row=fresh.data;}if(!current(ticket)||seq!==detailSeq||!detailOpen.value)return;if(!await api.value.verify(row,original.patient_id,original.admission_id,true))throw new Error("SOFA撤销后完整冻结审计未能重核");if(!current(ticket)||seq!==detailSeq||!detailOpen.value)return;detail.value=row;reason.value="";await load();}catch(failure){if(current(ticket)&&seq===detailSeq)detailError.value=failure?.message||"SOFA冻结评估撤销失败";}finally{if(current(ticket)&&seq===detailSeq)acting.value=false;}}
watch(()=>supportCanonical(filters.value),()=>{listSeq++;detailOpen.value=false;clearDetail();items.value=[];total.value=0;page.value=1;},{flush:"sync"});watch(session,()=>{reset();load();},{immediate:true,flush:"sync"});onDeactivated(()=>{paused=true;reset();});onActivated(()=>{if(paused){paused=false;reset();load();}});onBeforeUnmount(()=>{alive=false;reset();});
</script>
<style scoped>p{line-height:1.7}.hash,pre{overflow-wrap:anywhere;white-space:pre-wrap}.el-button{margin:8px 8px 8px 0}</style>
